void unit_test_update_non_head_node_all_fields_non_zero(void) {
    // Setup: create a linked list with at least two nodes
    // We'll use the insert function from the operation map to build the list
    struct node *root = NULL;
    // Insert first node (ID 1)
    insert(&root, 1, 0, 5, 1);
    // Insert second node (ID 2) - this will be the target node for update
    insert(&root, 2, 1, 4, 2);
    // Insert third node (ID 3) to ensure we traverse past head
    insert(&root, 3, 2, 3, 3);

    // Initialize fields to known values (all zero as per insert)
    // Verify initial state
    struct node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: update the non-head node (ID 2) with all non-zero values
    // This triggers the target path:
    // 1. ptr = *root
    // 2. if (ptr != NULL && ptr->ID == id) -> FALSE (head ID is 1, target is 2)
    // 3. while (ptr != NULL && ptr->ID != id) -> loop until ID 2 found
    // 4. After loop: ct != 0 -> TRUE, wt != 0 -> TRUE, tat != 0 -> TRUE
    // 5. All three fields are updated
    int new_ct = 10;
    int new_wt = 5;
    int new_tat = 15;
    update(&root, 2, new_ct, new_wt, new_tat);

    // Assertions: verify the target node was updated
    ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(new_wt, ptr->WT);
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged
    ptr = root; // head node (ID 1)
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    ptr = root->next->next; // third node (ID 3)
    TEST_ASSERT_EQUAL_INT(3, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

