    // Use delete function from operation map to remove nodes one by one
    delete(&root, 1);
    delete(&root, 2);
    delete(&root, 3);
    TEST_ASSERT_NULL(root);
    // Additional cleanup to ensure no memory leaks
    helper_cleanup_process_queue(&root);
}

